/*
 * Clackling sprites: 24x24 text art, one per stage and pose, generated by
 * scripts/gen_pet_sprites.py. Pure data so it can be tested on the host.
 */
#pragma once

#include "pet_core.h"

#define PET_SPRITE_W 24
#define PET_SPRITE_H 24

/* palette chars: '.' transparent, '#' outline, 'o' body, '*' accent, 'w' shine */
enum pet_pose { PET_POSE_IDLE, PET_POSE_BOUNCE, PET_POSE_SLEEP, PET_POSE_HUNGRY,
                PET_POSE_CHEER, PET_POSES };

/* PET_SPRITE_H strings of PET_SPRITE_W chars */
const char *const *pet_sprite(enum pet_stage stage, enum pet_pose pose);
